content.query:
let SelectedCorrelationId = '{CorrelationId}';
let WorkflowSteps =
    LogicAppWorkflowRuntime
    | where TrackedProperties has SelectedCorrelationId
    | extend Tracked = parse_json(tostring(TrackedProperties))
    | where tostring(Tracked.correlationId) == SelectedCorrelationId
    | project TimeGenerated, Source = "Logic Apps", Name = WorkflowName, Step = ActionName, Status, AutomationJobId = tostring(Tracked.automationJobId), Worker = tostring(Tracked.worker), ErrorCode = tostring(Tracked.errorCode);
// Automation job logs carry Automation's own correlation ID: they are joined through the job ID J3 tracks.
let JobIds = WorkflowSteps | where isnotempty(AutomationJobId) | distinct AutomationJobId;
let AutomationJobs =
    AzureDiagnostics
    | where Category == "JobLogs"
    | where tostring(JobId_g) in (JobIds)
    | project TimeGenerated, Source = "Automation job", Name = RunbookName_s, Step = strcat("Job ", ResultType), Status = ResultType, AutomationJobId = tostring(JobId_g), Worker = RunOn_s, ErrorCode = "";
union WorkflowSteps, AutomationJobs
| order by TimeGenerated asc
